namespace Gordic.Ada.WebClient {

    interface GHromadneOperaceDialog {
        getFormData(): object;
    }

    @Decorators.gcontent
    export class GAkceHromadneOperaceTab extends GContentBase {

        uid = "HromadneOperace#";
        private $grid: JQuery;
        formCnt: GContent & GHromadneOperaceDialog;
        gridFormat: Data.GridFormat;
        form: JQuery;
        rs: JQuery;
        actAll: GAction;
        actSuccess: GAction;
        actWarning: GAction;
        actError: GAction;

        badgeAll: GObservableObject<GBadgeOptions>;
        badgeSuccess: GObservableObject<GBadgeOptions>;
        badgeWarning: GObservableObject<GBadgeOptions>;
        badgeError: GObservableObject<GBadgeOptions>;
        prepareContent(args: HromadneOperaceInputOptions<any>) {

            var that = this;
            var dataView = new Gordic.Data.View<Ada.Interface.GAkceDto & { vysledek: string, stav: number }>(args.data, args.viewSettings);
            var serviceContent = new GContent("Gordic.Ada.WebClient.GAkceHromadneOperaceTab");          // serverový objekt
            var wizard = new Gordic.Wizard();                                                       // definice wizardu
            var l_sNazevOperace = "Další";                                                           // Default
            var l_sTitulekOperace = "Hromadná operace";                                                // Hromadná operace
            var l_sValidacniFunkce = "";                                                            // Funkce pro validaci operace
            var l_sVykonnaFunkce = "";                                                              // Funkce pro vykonání operace
            var l_oDialog: string | GHromadneOperaceDialogType = "";                                // Dialog s doplňkovými informacemi
            var l_nKrok = -1;                                                                       // čísla kroků - pro případ, že bude první krok chybět
            var l_oDoplnujiciTlacitka: MenuParams[] = [];                                           // proměnná pro doplňující tlačítka k hromadné operaci

            // ************************
            //  Dodatečné vlastní akce
            // ************************
            var buttonTisk: MenuParams = {                                                          // Tlačítko TISK
                caption: "Tisk",                                                                    // Tisk
                
                action: new GAction({                                                               // Definice akce
                    icon: "gi-print g-state-success g-state-text",                                  // ikona
                    name: "actTisk",                                                                // pojmenování akce
                    run: () => {
                        alert("Akce není implementována.");
                    }
                })
            }

            // ************************
            //   Tlačítko PŘEEVIDENCE
            // ************************
            var buttonPreevidence: MenuParams = {                                                   // Tlačítko PŘEEVIDENCE
                caption: "Kopie akcí",                                                           // RC 29750252 : Přeevidence
                action: new GAction({                                                               // Definice akce
                    icon: "fa-reply g-state-success g-state-text",                                  // ikona
                    name: "actPreevidence",                                                         // pojmenování akce
                    run: () => {
                        alert("Akce není implementována.");
                    }
                })
            }


            l_sTitulekOperace = " Hromadná operace - Kopie";                                // RC 29750232 : Hromadná operace - STORNO
            l_sNazevOperace = "Kopírovat";                                                  // Kopírovat
            l_sValidacniFunkce = "LzeKopieAkce";                                      // Funkce pro validaci operace
            l_sVykonnaFunkce = "KopieAkce";                                           // Funkce pro vykonání operace
            l_oDoplnujiciTlacitka = [buttonTisk];                                           // Doplňková tlačítka
            l_oDialog = Gordic.Ada.WebClient.GAkceKopieDlgClient;                       // Dialog s doplňkovými informacemi

            var l_bSDialogem = true; //l_oDialog !== "";                                                    // indikace, zda hromadná operace má doplňující dialog

            //#region 1. Krok
            // ***********************************************************
            //    1. krok - zadání doplňujících informací
            // ***********************************************************
            var krokPrvni =
            {
                caption: "Doplňující informace",                                                           //Doplňující informace
                create: function (cnt, $element?, ctx?) {                                           // vytvoření nového kroku
                    l_nKrok = 0;                                                                    // 1. krok
                    //var parametry = {
                    //    ListIxp: args.data.map(function (d) { return d.ixp; }),                   // seznam vybraných dokladů (ixp)
                    //    HromadnaAkce: true                                                        // hromadné akce povoleny
                    //};

                    if (l_bSDialogem == true) {                                                     // hromadná operace s dialogem
                        if (that.form == null) {                                                    // form ještě neexistuje
                            that.form = $("<div>").appendTo(cnt.element)                            // přidej DIV na můj element
                                .gcontent(l_oDialog);                                               // políčka pro doplňující informace
                            cnt.beginOperation();                                                   // indikátor procesu - START
                            if (typeof l_oDialog == "string") {                                     // jde o přímé volání dialogu v TS 
                                that.form.gcontent("load"/*, parametry*/)                           // nahrání dialogu s parametry
                                    .done(function () {
                                        cnt.endOperation();                                         // indikátor procesu - KONEC    
                                    });
                            } else {                                                                // jde o volání serveru CS
                                cnt.endOperation();                                                 // indikátor procesu - KONEC    
                            }

                            cnt.formCnt = $.content(that.form);                                     // upřesňující dialog
                        } else {                                                                    // form již existuje
                            that.form.findFields().gfield("enable");                                // políčka budou opět přístupná
                            that.rs.hide();                                                         // div s výsledkem již existuje, tak ho schovám
                        }
                    }

                    if (cnt.$grid == null) {                                                        // grid ještě neexistuje
                        var gf = new Gordic.Data.GridFormat();                                      // inicializace gridformátu
                        gf.addIconColumn({                                                          // přidání výsledkového sloupce do gridu wizardu
                            name: "vysledek", caption: "Výsledek", width: 170,                      // vlastnosti přidaného sloupce
                            hidden: true,
                            iconTemplate: function (data) {                                         // sloupec do gridu timu ICON
                                if (data.stav === Gordic.Isl.GOperationResultKind.Success)          // vyhovující doklad
                                    return { icon: "fa-check-circle g-state-success g-state-text", text: "OK", tooltip: "Vyhovující doklad pro hromadnou operaci" };
                                else if (data.stav === Gordic.Isl.GOperationResultKind.Warning)     // vyhovující doklad s upozrněním
                                    return { icon: "fa-check-circle g-state-warning g-state-text", text: data.vysledek, tooltip: "Doklad s upozorněním" };
                                else if (data.stav === Gordic.Isl.GOperationResultKind.Error)       // nevyhovující doklad
                                    return { icon: "fa-times-circle g-state-error g-state-text", text: data.vysledek, tooltip: "Nevyhovující doklad pro hromadnou operaci" };
                                else                                                                // žádný výsledek neexistuje
                                    return { icon: "fa-fw", text: "", tooltip: "" };                     // neutrální doklad
                            }
                        });
                        gf.add(args.columns);                                                       // přidání sloupců ze seznamu pro grid wizasrdu
                        cnt.gridFormat = gf;                                                        // přidělení gridformátu pro grid

                        // GRID
                        cnt.$grid = $("<div>").appendTo(cnt.element)                                // přidání elementu
                            .gautofit()
                            .ggrid({
                                multiMenu: [{ action: new GAction({ name: "actSelectOk", caption: "Vybrat vyhovující", run: function () { } }) }],
                                columnMode: "full",
                                selection: function (ev, ctx) {
                                    l_nKrok = wizard.getStep(cnt);                                  // zjištění akturální kroku
                                    let enabled = false;                                            // indikace, zda bude další krok přístupný
                                    if (l_nKrok == 0 && l_bSDialogem == true)                       // 1. krok ze 3.
                                        enabled = that.checkData(ctx.view);                         // musí být aspoň jeden doklad vybraný
                                    if (l_nKrok == 0 && l_bSDialogem == false || l_nKrok == 1 && l_bSDialogem == true) // 1. krok ze 2 nebo 2. krok ze 3
                                        enabled = that.checkValidData(ctx.view) == true;            // musí být aspoň jeden doklad vybraný a ještě validní

                                    if (l_nKrok == 0 && l_bSDialogem == false)                      // 1. krok ze 2
                                        wizard.enableStep(cnt, [{ index: l_nKrok + 1, enabled }], { next: { enabled } });
                                    else if (l_nKrok == 0 && l_bSDialogem == true)                  // 1. krok ze 3
                                    {
                                        wizard.enableStep(cnt, [{ index: l_nKrok + 1, enabled }], { next: { enabled } });
                                        wizard.enableStep(cnt, [{ index: l_nKrok + 2, enabled: false }], { next: { enabled: false } });
                                    }
                                    else if (l_nKrok == 1 && l_bSDialogem == true)                  // 2. krok ze 3
                                        wizard.enableStep(cnt, [{ index: l_nKrok - 1, enabled: true }], { next: { enabled: true } });
                                        wizard.enableStep(cnt, [{ index: l_nKrok + 1, enabled }], { next: { enabled } });
                                },
                                multi: true,
                                columns: gf,
                                data: []
                            });

                        var rows = dataView.getDataRows(true);                                      // řádky
                        for (var i = 0, length = rows.length; i < length; i++) {                    // projedu všechny řádky
                            rows[i].checked = true;                                                 // zaškrtnu to
                        }

                        cnt.$grid.ggrid("setData", dataView);                                       // nastavení dat do gridu
                    } else {                                                                        // grid již existuje
                        cnt.gridFormat.get("vysledek").hidden = true;                               // v 1. kroku bude sloupec "Výsledek" neviditelný
                        cnt.$grid.ggrid("option", "columns", cnt.gridFormat);                       // aktualizace grid formátu
                    }

                    return cnt.$grid;                                                               // vrácení hotového gridu
                },
                change: function (cnt, $element, ctx) {                                             // event na změnu kroku
                    if (l_bSDialogem == true) cnt.formCnt.element.findFields().gfield("validate");  // ruční spuštění validace doplňujícíhi dialogu
                    ctx.stepsEnable[1] = cnt.formCnt.element.findForms().gform("isValid");          // další krok bude přístupný, až bude vše v dialogu validní
                }
            };
            //#endregion

            //#region 2. Krok
            // **************************************************************
            //    2. krok - validace dokladů, zda bude hromadná operace možná
            //   **************************************************************
            var krokDruhy = {
                caption: "Kontrola akcí",                                                           // Kontrola dokladů
                commandBar: { previously: "Předchozí", next: l_sNazevOperace },                     // vlastní názvy tlačítek
                create: function (cnt, $element, ctx) {                                             // vytvoření nového kroku
                    cnt.beginOperation("Probíhá kontrola");                                         // Probíhá kontrola stavu vybraných dokladů ...

                    if (l_bSDialogem == true) {                                                     // hromadná operace s dialogem
                        that.form.findFields().gfield("disable");                                   // všechna políčka doplňujících informací budou needitovatelná
                        l_nKrok = 2;                                                                // toto je 2. krok
                    } else {                                                                        // hromadná operace bez dialogu
                        krokPrvni.create(cnt);                                                      // vytvoření části CREATE prvního kroku
                        //l_nKrok = 1;                                                                // toto je 1. krok
                    }

                    cnt.gridFormat.get("vysledek").hidden = false;                                  // v 2. kroku bude sloupec "Výsledek" viditelný
                    cnt.$grid.ggrid("option", "columns", cnt.gridFormat);                           // aktualizace grid formátu

                    var dialogData = l_bSDialogem ? cnt.formCnt.getFormData() : undefined;          // posbíraná data z dialogu

                    // Vykonání validační operace
                    serviceContent.call(l_sValidacniFunkce, { doklady: args.data.map(function (d) { return { rok: d.rok, ico: d.ico, cislo: d.cislo } }), data: dialogData })
                        .done(function (result: { result: { data: Ada.Interface.GAkceDto, errors: { message: string }[], kind: Gordic.Isl.GOperationResultKind }[] }) {

                        var l_oVysledky = result.result;                                            // načtení výsledků
                        var l_nUspesne = 0;                                                         // počet úspěšných dokladů
                        var l_nUspesneSVarovanim = 0;                                               // počet dokladů s varováním
                        var l_nNeuspesne = 0;                                                       // počet neúspěšných dokladů

                        for (var i = 0, l = l_oVysledky.length; i < l; i++) {                       // projedu všechny řádky
                            var item = l_oVysledky[i];                                              // jednotlivý výsledek 
                            var l_oRadek = dataView.verify( item.data, true);                       // řádek z gridu
                            if (l_oRadek != null)                                                   // pokud řádek není prázdný
                            {
                                l_oRadek.data.vysledek = (item.errors === undefined) ? "OK" : l_oRadek.vysledek = item.errors[0].message; // doplní k řádku výsledný stav kontroly dokladu
                                l_oRadek.data.stav = item.kind;                                     // doplění stavu do dokladu
                                if (item.kind === Gordic.Isl.GOperationResultKind.Success)          // je to v pořádku
                                { l_nUspesne++; l_oRadek.checked = true; }                          // navýšení počtů a zaškrtnutí řádku
                                else if (item.kind === Gordic.Isl.GOperationResultKind.Warning)     // je to s upozorněním
                                { l_nUspesneSVarovanim++; l_oRadek.checked = true }                 // navýšení počtů a zaškrtnutí řádku
                                else if (item.kind === Gordic.Isl.GOperationResultKind.Error)       // je to s chybou
                                { l_nNeuspesne++; l_oRadek.checked = false }                        // navýšení počtů a odškrtnutí řádku
                            }
                        }

                        that.badgeAll = new GObservableObject<GBadgeOptions>({ value: l_oVysledky.length.toString(), customClass: "g-state-background g-state-info" });
                        that.badgeSuccess = new GObservableObject<GBadgeOptions>({ value: l_nUspesne.toString(), customClass: "g-state-background g-state-success" });
                        that.badgeWarning = new GObservableObject<GBadgeOptions>({ value: l_nUspesneSVarovanim.toString(), customClass: "g-state-background g-state-warning" });
                        that.badgeError = new GObservableObject<GBadgeOptions>({ value: l_nNeuspesne.toString(), customClass: "g-state-background g-state-error" });

                        that.actAll = new GAction({                                                                      // VŠECHNY DOKLADY
                            name: "actAll", caption: "Všechny doklady",                                                  // Všechny doklady
                            run: function () { that.zaskrtniRadky(dataView, Gordic.Isl.GOperationResultKind.Info) }
                        });   // zaškrtnutí všech dokladů
                        that.actSuccess = new GAction({                                                                  // SUCCESS
                            name: "actSuccess", caption: "Vyhovující doklady",                                           // Vyhovující doklady
                            run: function () { that.zaskrtniRadky(dataView, Gordic.Isl.GOperationResultKind.Success)} });// zaškrtnutí success dokladů
                        that.actWarning = new GAction({                                                                  // WARNING
                            name: "actWarning", caption: "Doklady s upozorněním",                                        // Doklady s upozorněním
                            run: function () { that.zaskrtniRadky(dataView, Gordic.Isl.GOperationResultKind.Warning)} });// zaškrtnutí warning dokladů
                        that.actError = new GAction({                                                                    // ERROR
                            name: "actError", caption: "Nevyhovující doklady",                                           // Nevyhovující doklady
                            run: function () { that.zaskrtniRadky(dataView, Gordic.Isl.GOperationResultKind.Error)} });  // zaškrtnutí error dokladů          

                        // Zobrazení výsledků
                        if (that.rs == null) {                                                      // div s výsledkem ještě neexistuje
                            that.rs = $("<div class='statusbar'>")                                  // zobrazení výsledkové lišty
                                .insertBefore(cnt.$grid)                                            // vložení před grid
                                .gbuttonpanel({
                                    params:
                                        [{ action: that.actAll, badge: that.badgeAll },             // všechny doklady
                                         { action: that.actSuccess, badge: that.badgeSuccess },     // OK doklady
                                         { action: that.actWarning, badge: that.badgeWarning },     // warnings doklady
                                         { action: that.actError, badge: that.badgeError }]         // KO doklady
                                })
                        } else {                                                                    // div s výsledkem již existuje
                            that.rs.show();                                                         // zobrazím ho    
                        }
                        dataView.refresh();                                                         // občerstvení dat
                        cnt.$grid.ggrid("refreshRows");                                             // občerstvení dat do gridu

                    }).always(function () {
                        // that.showFlash("Budete proveden průvodcem :-)", "g-state-info", 5000, "id-flash-first-step");
                        cnt.endOperation();                                                         // konec indikátoru procesus
                    });                                 
                },
                change: function (cnt, $element, ctx) {                                             // event na změnu kroku

                }
            };
            //#endregion

            //#region 3. Krok
            // ***********************************************************
            //    3. krok - výsledky hromadné operace
            // ***********************************************************
            var krokTreti = {
                caption: "Výsledek",                                                                // Výsledek
                commandBar: { previously: "", next: "Zavřít" },                                     // vlastní názvy tlačítek
                buttons: l_oDoplnujiciTlacitka,                                                     // přidání dodatečných tlačíteks
                create: function (cnt, $element, ctx) {                                             // vytvoření nového kroku
                    cnt.beginOperation("Probíhá hromadná operace");                                            // Probíhá hromadná operace na vybraných dokladech ...

                    dataView.process(new Data.BaseProcessor({                                       // proces na poslanými daty
                        tiers: { filter: {} }, process: (tiers, data, ctx) => {                     // přes filtr vybere pouze zaškrtnuté záznami
                            return data.slice(0).filter((it) => it.checked);                        // a vrátí data jako nezávislou kopii zaškrtnutých dat
                        }
                    }));

                    var dialogData = l_bSDialogem ? cnt.formCnt.getFormData() : undefined;          // posbíraná data z dialogu
                    // Vykonání hromadné operace
                    serviceContent.call(l_sVykonnaFunkce, { doklady: dataView.getDataRows(true).map((it) => { return { rok: it.data.rok, ico: it.data.ico, cislo: it.data.cislo } }), data: dialogData }).done(function (result: { result: { data: Ada.Interface.GAkceDto, errors: { message: string }[], kind: Gordic.Isl.GOperationResultKind }[] }) {

                        var l_oVysledky = result.result;                                            // načtení výsledků
                        var l_nUspesne = 0;                                                         // počet úspěšných dokladů
                        var l_nNeuspesne = 0;                                                       // počet neúspěšných dokladů

                        for (var i = 0, l = l_oVysledky.length; i < l; i++) {                       // projedu všechny řádky
                            var item = l_oVysledky[i];                                              // jednotlivý výsledek 
                            var l_oRadek = dataView.verify(item.data, true);                // řádek z gridu
                            if (l_oRadek != null)                                                   // pokud řádek není prázdný
                            {
                                l_oRadek.data.vysledek = (item.errors === undefined) ? "OK" : l_oRadek.data.vysledek = item.errors[0].message; // doplní k řádku výsledný stav kontroly dokladu
                                l_oRadek.data.stav = item.kind;                                     // doplění stavu do dokladu
                                if (item.kind === Gordic.Isl.GOperationResultKind.Success)          // je to v pořádku
                                { l_nUspesne++; l_oRadek.checked = true }                           // navýšení počtů a zaškrtnutí řádku
                                else if (item.kind === Gordic.Isl.GOperationResultKind.Error)       // je to s chybou
                                { l_nNeuspesne++;  }                                                // navýšení počtů a odškrtnutí řádku
                            }
                        }
                        // Zobrazení výsledku - změna textů a hodnot
                        that.actSuccess.update({ caption: "Změněné doklady" });                     // OK doklady, změna titulku // TODO
                        that.actError.update({ caption: "Nezměněné doklady" });                     // KO doklady, změna titulku // TODO

                        that.badgeAll.update({ value: l_oVysledky.length.toString() });             // změna počtu všech dokladů
                        that.badgeSuccess.update({ value: l_nUspesne.toString() });                 // změna počtu úspěšných dokladů
                        that.actWarning.visible(false);                                             // schování warningu
                        that.badgeError.update({ value: l_nNeuspesne.toString() });                 // změna počtu neúspěšných dokladů

                        dataView.refresh();                                                         // občerstvení dat
                        cnt.$grid.ggrid("refreshRows");                                             // občerstvení dat do gridu

                    }).always(function () {                                                         // vždy    
                        cnt.endOperation();                                                         // konec indikátoru procesu
                    });
                },
                change: function (cnt, $element, ctx) {                                             // event na změnu kroku
                    ctx.stepsEnable[0] = false;                                                     // 1. krok nebude přístupný
                    if (l_bSDialogem)                                                               // pokud existuje doplňkový dialog
                        ctx.stepsEnable[1] = false;                                                 // 2. krok nebude přístupný
                }
            };
            //#endregion

            wizard.create(                                                                          // vytvoření wizardu
                {
                    content: this
                },
                {
                    title: l_sTitulekOperace,                                                       // nastvení titulku
                    // steps: l_oDialog === "" ? [krokDruhy, krokTreti] : [krokPrvni, krokDruhy, krokTreti], // konec přidávání kroků
                    steps: [krokPrvni, krokDruhy, krokTreti], // konec přidávání kroků
                    complete: function (cnt) { cnt.close(); },                                      // zavření WIZARDu
                })
        }

        // ******************************************************************
        //   Funkce pro kontrolu zaškrtnutí v gridu, zda je něco zaškrtnuto
        // ******************************************************************
        checkData(dataView: Gordic.Data.View<Ada.Interface.GAkceDto & { vysledek: string }>) {
            var data = dataView.getDataRows(true);

            for (var i = 0, l = data.length; i < l; i++) {                                          // projedu všechny řádky z gridu
                var item = data[i];                                                                 // řádek z gridu
                if (item.checked) return true;                                                      // je zaškrtnutý a nevyhovující
            }
            return false;                                                                           // nic není zaškrtnuto
        }
        // ****************************************************************************
        //   Funkce pro kontrolu zaškrtnutí v gridu, zda je na vyhovujících dokladech
        // ****************************************************************************
        checkValidData(dataView: Gordic.Data.View<Ada.Interface.GAkceDto & { vysledek: string, stav: number }>) {
            var data = dataView.getDataRows(true);

            for (var i   = 0, l = data.length; i < l; i++) {                                        // projedu všechny řádky z gridu
                var item = data[i];                                                                 // řádek z gridu
                if (item.checked && item.data.stav == Isl.GOperationResultKind.Error) return false; // je zaškrtnutý a nevyhovující
            }

            if (this.$grid == undefined) return false;
            return this.$grid.ggrid("getSelection", true, true).length > 0;                         // všechny řádky jsou OK
        }

        // ****************************************************
        //   Funkce pro zaškrtnutí zvolených dokladů v gridu
        // ****************************************************
        zaskrtniRadky(dataView: Gordic.Data.View<Ada.Interface.GAkceDto & { vysledek: string, stav: number }>, kind: Gordic.Isl.GOperationResultKind) {
            var data = dataView.getDataRows(true);

            for (var i = 0, l = data.length; i < l; i++) {                                          // projedu všechny řádky z gridu
                var item = data[i];                                                                 // řádek z gridu
                if (kind === Isl.GOperationResultKind.Info)                                         // INFO = všechny doklady
                    item.checked = true;                                                            // zaškrtnout řádek
                else if (item.data.stav === kind)                                                   // je doklad v požadovaném stavu
                    item.checked = true;                                                            // zaškrtnout řádek
                else                                                                                // není to v pořádku
                    item.checked = false;                                                           // odškrtnout řádek
            }
            dataView.refresh();                                                                     // občerstvení dat
            this.$grid.ggrid("refreshRows");                                                        // občerstvení dat do gridu
        }
    }

    export interface HromadneOperaceInputOptions<TData> {
        data: TData[]
        columns: Gordic.Data.GridFormat<TData>
        viewSettings?: any,
        operace: "" //HromadneOperace
    }
}